/**
 * Whaleal IDP 认证（OAuth2 Authorization Code + PKCE）—— 主站实现。
 *
 * 为什么不用 @melody-auth/react：sms 侧在 1.0.11 上踩到 state 解析缺陷
 * （web-sdk `loadCodeAndStateFromUrl` 手写 `split('=')` 解析、不做解码，自定义 state 会被截断，
 * 表现为 "Can not obtain access token"），已整体替换为自实现。主站与之对齐，
 * 保持生态内**同一套登录逻辑**（API 形状也沿用 sms 的 useAuth）。
 *
 * IDP 端点是标准 OAuth2（已核对源码与线上）：
 *   GET  {server}/oauth2/v1/authorize?response_type=code&client_id&redirect_uri
 *        &scope&code_challenge&code_challenge_method=S256&state[&policy][&locale]
 *   POST {server}/oauth2/v1/token   (form: grant_type/code/code_verifier，SPA 无需 Basic)
 *   GET  {server}/oauth2/v1/logout?client_id&post_logout_redirect_uri
 *   POST {server}/identity/v1/logout  (Bearer，吊销 refresh token)
 *   GET  {server}/oauth2/v1/userinfo  (Bearer，兜底回填 email/name)
 *
 * 🔴 SSR 口径（Gatsby 构建期会真跑一遍 render）
 *   render 期间与 useState 初始化式里**不得触碰 window/localStorage/sessionStorage**，
 *   否则 `gatsby build` 直接崩；浏览器 API 只允许出现在 useEffect 与事件回调里。
 *   初始态固定为「认证中」，使 SSR 静态 HTML 与首帧客户端渲染**同形态**（否则 hydration 不匹配）。
 *
 * 🔴 资料类仍只做 launcher：下拉每一项都是 loginRedirect({ policy })，**不自建密码/改邮箱表单**。
 *   团队/组织走 IdP policy（create_org / manage_org）；换「当前组织」请登出后重登，无 change_org。
 *
 * @author 恒哥
 */
import React, {
  createContext, useCallback, useContext, useEffect, useMemo, useRef, useState,
} from 'react';
import { decodeJwtPayload, pkcePair, randomString } from './pkce';
import {
  IDP_SERVER_URL,
  IDP_WEB_CLIENT_ID,
  SITE_URL,
} from '../constants/brand';

const CLIENT_ID = IDP_WEB_CLIENT_ID;
const SERVER_URI = IDP_SERVER_URL;
/** redirect_uri 白名单只登记了根域 ⇒ 回调恒落首页，无需任何路由回跳 */
const REDIRECT_URI = SITE_URL;
const SCOPES = ['openid', 'profile', 'email', 'offline_access'];

const AUTHORIZE_URL = `${SERVER_URI}/oauth2/v1/authorize`;
const TOKEN_URL = `${SERVER_URI}/oauth2/v1/token`;
const LOGOUT_URL = `${SERVER_URI}/oauth2/v1/logout`;
/** OIDC 标准 userinfo：仅当本地推不出 email/name 时兜底调用 */
const USERINFO_URL = `${SERVER_URI}/oauth2/v1/userinfo`;
/** 当前用户所属组织列表（Bearer SPA token；与 token 内 org_id 对照出展示名/slug） */
const MY_ORGS_URL = `${SERVER_URI}/api/v1/me/orgs`;

/**
 * 存储键沿用 sms 的命名（两个站点不同源、互不影响），便于两套实现直接对照 diff。
 * - tokens：access/refresh/id token 与过期时间
 * - profile：账户展示信息快照，与 access_token 生命周期解耦（见下）
 * - SS_LOGIN：本次登录的 state + code_verifier（必须放 sessionStorage：仅当前标签页有效）
 */
const LS_TOKENS = 'wc.idp.tokens';
const LS_PROFILE = 'wc.idp.profile';
const SS_LOGIN = 'wc.idp.login';

/** 提前 60s 视为过期，触发静默续期 */
const EXPIRE_SLACK_MS = 60_000;

const AuthContext = createContext(null);

/* ------------------------------------------------------------------ *
 * 存储读写：全部带 try/catch（隐私模式 / 禁用存储时不应影响登录）
 * ------------------------------------------------------------------ */

function loadTokens() {
  try {
    const raw = localStorage.getItem(LS_TOKENS);
    return raw ? JSON.parse(raw) : null;
  } catch {
    return null;
  }
}

function saveTokens(tokens) {
  try {
    localStorage.setItem(LS_TOKENS, JSON.stringify(tokens));
  } catch { /* 忽略 */ }
}

function clearTokens() {
  try {
    localStorage.removeItem(LS_TOKENS);
  } catch { /* 忽略 */ }
}

function loadProfileSnapshot() {
  try {
    const raw = localStorage.getItem(LS_PROFILE);
    return raw ? JSON.parse(raw) : null;
  } catch {
    return null;
  }
}

function saveProfileSnapshot(profile) {
  try {
    localStorage.setItem(LS_PROFILE, JSON.stringify(profile));
  } catch { /* 忽略 */ }
}

function clearProfileSnapshot() {
  try {
    localStorage.removeItem(LS_PROFILE);
  } catch { /* 忽略 */ }
}

/* ------------------------------------------------------------------ *
 * token / 账户信息解析
 * ------------------------------------------------------------------ */

function orgIdFromPayload(payload) {
  if (!payload || payload.org_id == null) return undefined;
  const id = Number(payload.org_id);
  return Number.isFinite(id) ? id : undefined;
}

/**
 * 导航触发器文案：团队登录 → 组织 display name；个人空间 → 用户姓名（非邮箱）。
 */
function orgNavLabel({ orgType, orgName, orgSlug, personName }) {
  if (orgType === 'organization') {
    return orgName?.trim() || orgSlug || undefined;
  }
  if (orgType === 'personal') {
    const display = personName?.trim();
    if (display) return display;
    return orgName?.trim() || undefined;
  }
  return orgName?.trim() || orgSlug || personName?.trim() || undefined;
}

function accountFromPayload(payload) {
  if (!payload) return {};
  // 非邮箱的 username（IDP 允许手机号/用户名登录）不冒充 email，退到「姓名」位展示
  const username = payload.username ?? payload.preferred_username;
  const rawEmail = payload.email ?? username;
  // IDP 的 id_token 用 snake_case 的 first_name / last_name，没有 name 字段
  const composedName = [payload.first_name, payload.last_name].filter(Boolean).join(' ');
  const name = payload.name ?? (composedName || undefined) ?? payload.given_name ?? payload.nickname;
  return {
    email: typeof rawEmail === 'string' && rawEmail.includes('@') ? rawEmail : undefined,
    name: name ?? (typeof username === 'string' && !username.includes('@') ? username : undefined),
    roles: payload.roles,
    sub: payload.sub ?? payload.authId,
    orgId: orgIdFromPayload(payload),
    orgType: payload.org_type ?? payload.orgType,
  };
}

/**
 * 从 id_token 提取账户展示信息（无 id_token 时返回 null）。
 * 刻意不校验 exp：这里只用于界面展示，不是鉴权依据。
 */
function profileFromIdToken(tokens) {
  if (!tokens?.idToken) return null;
  const account = accountFromPayload(decodeJwtPayload(tokens.idToken));
  return account.email || account.name ? account : null;
}

/** 按字段合并：patch 里为空的字段不覆盖 base（userinfo 可能缺 name/roles） */
function mergeAccount(base, patch) {
  return {
    email: patch.email ?? base?.email,
    name: patch.name ?? base?.name,
    roles: patch.roles?.length ? patch.roles : base?.roles,
    sub: patch.sub ?? base?.sub,
    orgId: patch.orgId ?? base?.orgId,
    orgName: patch.orgName ?? base?.orgName,
    orgSlug: patch.orgSlug ?? base?.orgSlug,
    orgType: patch.orgType ?? base?.orgType,
  };
}

/** 用 access_token 内的 org_id 在 /me/orgs 里解析当前组织的显示名与 slug。 */
async function fetchCurrentOrgContext(accessToken) {
  const payload = decodeJwtPayload(accessToken);
  const orgId = orgIdFromPayload(payload);
  if (orgId == null) return null;
  try {
    const res = await fetch(MY_ORGS_URL, {
      headers: { Authorization: `Bearer ${accessToken}` },
    });
    if (!res.ok) return null;
    const data = await res.json();
    const rows = data?.orgs;
    if (!Array.isArray(rows)) return null;
    const row = rows.find((item) => item?.org?.id === orgId);
    if (!row?.org) return null;
    return {
      orgId: row.org.id,
      orgName: row.org.name,
      orgSlug: row.org.slug,
      orgType: row.org.type,
    };
  } catch {
    return null;
  }
}

/**
 * 兜底回填：用 access_token 调 IDP userinfo 拿 email/姓名/roles。
 */
async function fetchUserInfo(accessToken) {
  try {
    const res = await fetch(USERINFO_URL, {
      headers: { Authorization: `Bearer ${accessToken}` },
    });
    if (!res.ok) return null;
    const data = await res.json();
    if (!data?.email && !data?.authId) return null;
    return {
      email: data.email?.includes('@') ? data.email : undefined,
      name: [data.firstName, data.lastName].filter(Boolean).join(' ') || undefined,
      roles: data.roles,
      sub: data.authId,
    };
  } catch {
    return null;
  }
}

async function requestToken(body) {
  const res = await fetch(TOKEN_URL, {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams(body).toString(),
  });
  if (!res.ok) {
    const text = await res.text().catch(() => '');
    throw new Error(`token exchange failed (${res.status}): ${text || res.statusText}`);
  }
  const data = await res.json();
  if (!data.access_token) throw new Error('token response missing access_token');
  const expiresIn = typeof data.expires_in === 'number' ? data.expires_in : 1800;
  return {
    accessToken: String(data.access_token),
    refreshToken: data.refresh_token ? String(data.refresh_token) : null,
    idToken: data.id_token ? String(data.id_token) : null,
    expiresAt: Date.now() + expiresIn * 1000,
  };
}

export function AuthProvider({ children }) {
  // 🔴 初始态必须与 SSR 一致：认证中 + 无 profile（profile 在 effect 里从快照恢复）
  const [isAuthenticating, setIsAuthenticating] = useState(true);
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [authenticationError, setAuthenticationError] = useState(null);
  const [tokens, setTokens] = useState(null);
  const [profile, setProfile] = useState(null);

  /** 并发去重：多组件同时 acquireToken 只发一次刷新请求 */
  const refreshingRef = useRef(null);
  /** 已尝试过 userinfo 回填的 access_token（防止「回填失败 → 反复请求」死循环） */
  const userInfoTriedRef = useRef(null);

  const applyTokens = useCallback((next) => {
    saveTokens(next);
    setTokens(next);
    setAuthenticationError(null);
    setIsAuthenticated(true);
    setIsAuthenticating(false);
    // 登录/恢复会话时刷新账户快照，之后即使 id_token 丢失也能稳定展示
    const fromId = profileFromIdToken(next);
    if (fromId) {
      saveProfileSnapshot(fromId);
      setProfile(fromId);
    }
  }, []);

  const fail = useCallback((message) => {
    // 主站导航栏没有空间展示错误；至少让它可被排查（控制台 + 按钮 title）
    console.error('[whaleal-auth]', message);
    setAuthenticationError(message);
    setIsAuthenticated(false);
    setIsAuthenticating(false);
  }, []);

  const exchangeCode = useCallback(async (code) => {
    const loginRaw = sessionStorage.getItem(SS_LOGIN);
    if (!loginRaw) throw new Error('登录会话已失效，请重新点击 Sign in');
    const { codeVerifier } = JSON.parse(loginRaw);
    const next = await requestToken({
      grant_type: 'authorization_code',
      code,
      code_verifier: codeVerifier,
      client_id: CLIENT_ID,
      redirect_uri: REDIRECT_URI,
    });
    sessionStorage.removeItem(SS_LOGIN);
    return next;
  }, []);

  const refresh = useCallback(async (opts) => {
    if (refreshingRef.current) return refreshingRef.current;
    const current = loadTokens();
    if (!current?.refreshToken) throw new Error('no refresh token');
    const body = {
      grant_type: 'refresh_token',
      refresh_token: current.refreshToken,
      client_id: CLIENT_ID,
    };
    if (opts?.orgId != null) {
      body.org_id = String(opts.orgId);
    }
    const pending = requestToken(body).then((next) => {
      // 刷新响应**不给 id_token**（IDP 只签发新的 access_token），也保留旧 refresh_token。
      // 若把 idToken 覆盖成 null，账户信息就只剩 access_token 里的 sub/roles，界面退化成裸 UUID。
      const merged = {
        ...next,
        refreshToken: next.refreshToken ?? current.refreshToken,
        idToken: next.idToken ?? current.idToken,
      };
      applyTokens(merged);
      return merged;
    });
    refreshingRef.current = pending.finally(() => { refreshingRef.current = null; });
    return pending;
  }, [applyTokens]);

  /**
   * 强制 refresh。🔴 公约：主站不得传 opts.orgId 换租户；换组织只能登出重登（tenant-integration-contract §3.1）。
   */
  const refreshTokens = useCallback(async (opts) => {
    try {
      return await refresh(opts);
    } catch (e) {
      clearTokens();
      setIsAuthenticated(false);
      throw e;
    }
  }, [refresh]);

  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const code = params.get('code');
    const state = params.get('state');
    const error = params.get('error');

    const cleanUrl = () => window.history.replaceState(null, '', window.location.pathname);

    if (error) {
      // 先清 query 再报错，避免刷新页面重复报错
      cleanUrl();
      fail(`IDP 返回错误：${error}${params.get('error_description') ? ` - ${params.get('error_description')}` : ''}`);
      return;
    }

    if (code) {
      const loginRaw = sessionStorage.getItem(SS_LOGIN);
      let stateValid = false;
      if (loginRaw && state) {
        try {
          stateValid = JSON.parse(loginRaw).state === state;
        } catch { stateValid = false; }
      }
      if (!stateValid) {
        cleanUrl();
        fail('登录回调校验失败（state 不匹配或会话已失效），请重试');
        return;
      }
      exchangeCode(code)
        .then(applyTokens)
        .catch((e) => fail(e instanceof Error ? e.message : String(e)))
        .finally(cleanUrl);
      return;
    }

    // 无回跳：尝试恢复本地会话
    const stored = loadTokens();
    if (stored?.accessToken) {
      // 先铺上账户快照：静默续期后 id_token 可能不在，快照能免掉一次 userinfo 请求。
      // 🔴 只能在 effect 里读（render / useState 初始化式内读 localStorage 会炸 SSR）。
      const snapshot = loadProfileSnapshot();
      if (snapshot) setProfile(snapshot);

      if (stored.expiresAt > Date.now() + EXPIRE_SLACK_MS) {
        applyTokens(stored);
      } else if (stored.refreshToken) {
        refresh().catch(() => {
          clearTokens();
          fail('登录已过期，请重新登录');
        });
      } else {
        clearTokens();
        fail('登录已过期，请重新登录');
      }
    } else {
      // 未登录是正常状态，不算错误
      setIsAuthenticating(false);
    }
    // 只在挂载时执行一次（回调处理 / 会话恢复）
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  /**
   * 发起登录。
   * @param {{ policy?: string, locale?: string }} [opts]
   *   policy ∈ update_info / change_password / change_email（资料类入口，见 brand.js）
   */
  const loginRedirect = useCallback((opts) => {
    const state = randomString(32);
    void pkcePair().then(({ verifier, challenge }) => {
      sessionStorage.setItem(SS_LOGIN, JSON.stringify({ state, codeVerifier: verifier }));
      const query = new URLSearchParams({
        response_type: 'code',
        client_id: CLIENT_ID,
        redirect_uri: REDIRECT_URI,
        scope: SCOPES.join(' '),
        code_challenge: challenge,
        code_challenge_method: 'S256',
        state,
      });
      if (opts?.policy) query.set('policy', opts.policy);
      if (opts?.locale) query.set('locale', opts.locale);
      window.location.assign(`${AUTHORIZE_URL}?${query.toString()}`);
    });
  }, []);

  const acquireToken = useCallback(async () => {
    const current = tokens ?? loadTokens();
    if (!current?.accessToken) return null;
    if (current.expiresAt > Date.now() + EXPIRE_SLACK_MS) return current.accessToken;
    if (!current.refreshToken) {
      clearTokens();
      setIsAuthenticated(false);
      return null;
    }
    try {
      const fresh = await refresh();
      return fresh.accessToken;
    } catch {
      clearTokens();
      setIsAuthenticated(false);
      return null;
    }
  }, [tokens, refresh]);

  const logoutRedirect = useCallback((opts) => {
    const postLogoutUri = opts?.postLogoutRedirectUri ?? SITE_URL;
    const goOauthLogout = () => {
      const query = new URLSearchParams({
        client_id: CLIENT_ID,
        post_logout_redirect_uri: postLogoutUri,
      });
      window.location.assign(`${LOGOUT_URL}?${query.toString()}`);
    };

    // 置为 authenticating：本地已登出但还没跳走，避免界面闪回「未登录」
    setIsAuthenticating(true);
    const current = loadTokens();
    clearTokens();
    clearProfileSnapshot();
    setTokens(null);
    setProfile(null);
    setIsAuthenticated(false);

    if (!current?.refreshToken) {
      goOauthLogout();
      return;
    }

    // 第一步：吊销 refresh token（identity logout 需有效 Bearer access token）
    acquireToken()
      .then((accessToken) => {
        if (!accessToken) return undefined;
        return fetch(`${SERVER_URI}/identity/v1/logout`, {
          method: 'POST',
          headers: {
            Authorization: `Bearer ${accessToken}`,
            'Content-Type': 'application/x-www-form-urlencoded',
          },
          body: new URLSearchParams({
            refresh_token: current.refreshToken,
            post_logout_redirect_uri: postLogoutUri,
          }).toString(),
        }).catch(() => undefined);
      })
      .finally(goOauthLogout);
  }, [acquireToken]);

  /**
   * 账户展示信息：id_token 最权威 → 本地快照 → access_token（只有 sub/roles）。
   * 分三级是为了让「静默续期 / 直接刷新页面 / id_token 缺失」三种情况都能有邮箱可展示。
   */
  const account = useMemo(() => {
    const fromId = profileFromIdToken(tokens);
    const fromAccess = tokens ? accountFromPayload(decodeJwtPayload(tokens.accessToken)) : null;
    const merged = {
      email: fromId?.email ?? profile?.email ?? fromAccess?.email,
      name: fromId?.name ?? profile?.name ?? fromAccess?.name,
      roles: fromAccess?.roles?.length ? fromAccess.roles : (fromId?.roles ?? profile?.roles),
      sub: fromId?.sub ?? fromAccess?.sub ?? profile?.sub,
      orgId: fromAccess?.orgId ?? profile?.orgId,
      orgName: profile?.orgName,
      orgSlug: profile?.orgSlug,
      orgType: profile?.orgType ?? fromAccess?.orgType,
    };
    const navLabel = orgNavLabel({
      orgType: merged.orgType,
      orgName: merged.orgName,
      orgSlug: merged.orgSlug,
      personName: merged.name,
    });
    if (!merged.email && !merged.name && !merged.roles?.length && !merged.sub && !navLabel) {
      return null;
    }
    return { ...merged, navLabel };
  }, [tokens, profile]);

  /**
   * 自愈：本地推不出 email/name 时（典型场景＝历史会话的 id_token 被清空），
   * 用 access_token 调一次 userinfo 回填，避免用户被迫重新登录才能看到账户信息。
   */
  useEffect(() => {
    const accessToken = tokens?.accessToken;
    if (!isAuthenticated || !accessToken) return undefined;
    if (account?.email || account?.name) return undefined;
    if (userInfoTriedRef.current === accessToken) return undefined;
    userInfoTriedRef.current = accessToken;

    let cancelled = false;
    void fetchUserInfo(accessToken).then((info) => {
      if (cancelled || !info) return;
      const next = mergeAccount(profile, info);
      saveProfileSnapshot(next);
      setProfile(next);
    });
    return () => { cancelled = true; };
  }, [isAuthenticated, tokens, account, profile]);

  /** 导航展示当前组织（名称 · slug），数据来自 token.org_id + GET /me/orgs */
  useEffect(() => {
    const accessToken = tokens?.accessToken;
    if (!isAuthenticated || !accessToken) return undefined;

    let cancelled = false;
    void fetchCurrentOrgContext(accessToken).then((ctx) => {
      if (cancelled || !ctx) return;
      setProfile((prev) => {
        if (prev?.orgId === ctx.orgId && prev?.orgSlug === ctx.orgSlug) return prev;
        const next = mergeAccount(prev, ctx);
        saveProfileSnapshot(next);
        return next;
      });
    });
    return () => { cancelled = true; };
  }, [isAuthenticated, tokens?.accessToken]);

  const value = useMemo(() => ({
    isAuthenticated,
    isAuthenticating,
    authenticationError,
    account,
    tokens,
    loginRedirect,
    logoutRedirect,
    acquireToken,
    refreshTokens,
  }), [
    isAuthenticated, isAuthenticating, authenticationError, account, tokens,
    loginRedirect, logoutRedirect, acquireToken, refreshTokens,
  ]);

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

export function useAuth() {
  const ctx = useContext(AuthContext);
  if (!ctx) throw new Error('useAuth must be used within <AuthProvider>');
  return ctx;
}
