/**
 * 官网分析（GA4）工具
 *
 * 口径与红线：
 * - 采用 **Google Consent Mode v2**：默认 `analytics_storage=denied`，用户明确同意后才 update 成 granted。
 *   这样即使脚本已加载，未同意前也不会产生可识别访客的存储与上报。
 * - GA ID 为空（未在 GA 后台开通或本地开发）时，**所有函数静默 no-op**，不报错、不影响页面。
 * - 🔴 本模块只上报**聚合事件**，严禁上报 shop 域名、邮箱等可识别商家的信息。
 *
 * 归因分工（重要）：
 * GA4 只能看到 www.whaleal.com 上的访问与点击；**安装动作发生在 Shopify 域内，GA 跟不到**。
 * 因此「哪个渠道真的装了」靠把 UTM 拼进 OAuth URL（见 `buildTrackingUrl`），
 * 由后端落库 `installSource` 后与 `planType`/`installedAt` 关联。
 *
 * @author 恒哥
 */

/** GA4 Measurement ID；未开通时留空 —— 留空即全链路 no-op */
export const GA_MEASUREMENT_ID = process.env.GATSBY_GA_MEASUREMENT_ID || '';

/** localStorage 键：用户对分析的同意决定 */
export const CONSENT_KEY = 'whaleal_analytics_consent';

/** localStorage 键：首次落地时捕获的来源参数（跨页跳转不丢） */
export const SOURCE_KEY = 'whaleal_source';

const UTM_KEYS = ['utm_source', 'utm_medium', 'utm_campaign', 'utm_term', 'utm_content'];
const SOURCE_TTL_MS = 90 * 24 * 60 * 60 * 1000; // 90 天

function isBrowser() {
  return typeof window !== 'undefined';
}

function gaAvailable() {
  return Boolean(GA_MEASUREMENT_ID) && isBrowser() && typeof window.gtag === 'function';
}

/**
 * 当前同意状态：'granted' | 'denied' | null（未定）
 * @returns {string|null}
 */
export function getConsent() {
  if (!isBrowser()) return null;
  try {
    return window.localStorage.getItem(CONSENT_KEY);
  } catch (e) {
    return null;
  }
}

/**
 * 是否已就绪（可上报）：GA ID 已配置 + gtag 就绪 + 用户已同意
 * @returns {boolean}
 */
export function canTrack() {
  return Boolean(GA_MEASUREMENT_ID) && isBrowser() && getConsent() === 'granted' && gaAvailable();
}

/**
 * 记录用户对分析的同意决定
 * @param {'granted'|'denied'} decision
 */
export function setConsent(decision) {
  if (!isBrowser() || (decision !== 'granted' && decision !== 'denied')) return;
  try {
    window.localStorage.setItem(CONSENT_KEY, decision);
  } catch (e) {
    // 隐私模式下 localStorage 可能不可用；忽略即可，只是本次会话不再上报
  }
  if (!gaAvailable()) return;
  window.gtag('consent', 'update', {
    analytics_storage: decision,
    ad_storage: 'denied',
    ad_user_data: 'denied',
    ad_personalization: 'denied',
  });
  if (decision === 'granted') {
    // 同意后立刻补发一次 page_view，避免用户直接点同意时这次访问整体丢失
    window.gtag('event', 'page_view', { page_path: window.location.pathname });
  }
}

/**
 * 上报一个事件
 * @param {string} name 事件名（用小写下划线，与 GA4 约定一致）
 * @param {object} [params] 附加参数，只能是非识别性的（如 path / variant）
 */
export function trackEvent(name, params = {}) {
  if (!canTrack()) return;
  try {
    window.gtag('event', name, params);
  } catch (e) {
    // 上报失败不影响业务流程
  }
}

/**
 * 从当前 URL 捕获来源参数并存下（首次落地时执行一次）
 * 供 install 页组 OAuth URL 时读取，让来源能穿过 Shopify 那一跳。
 */
export function captureSourceParams() {
  if (!isBrowser()) return;
  try {
    if (window.localStorage.getItem(SOURCE_KEY)) return; // 已有首次来源，不覆盖
    const params = {};
    UTM_KEYS.forEach((k) => {
      const v = readQueryParam(k);
      if (v) params[k] = v;
    });
    // gclid / fbclid 等点击 ID：判断「付费流量」时有用
    ['gclid', 'fbclid', 'msclkid', 'ttclid'].forEach((k) => {
      const v = readQueryParam(k);
      if (v) params[k] = v;
    });
    const referrer = document.referrer || '';
    if (Object.keys(params).length === 0 && !isInternalReferrer(referrer)) return;
    window.localStorage.setItem(SOURCE_KEY, JSON.stringify({ params, referrer, ts: Date.now() }));
  } catch (e) {
    // 忽略
  }
}

/**
 * 读取已捕获的来源
 * @returns {{params: object, referrer: string, ts: number}|null}
 */
export function getSourceParams() {
  if (!isBrowser()) return null;
  try {
    const raw = window.localStorage.getItem(SOURCE_KEY);
    if (!raw) return null;
    const parsed = JSON.parse(raw);
    if (!parsed || typeof parsed.ts !== 'number') return null;
    // 过期视为自然流量，避免用几个月前的来源误导归因
    if (Date.now() - parsed.ts > SOURCE_TTL_MS) {
      window.localStorage.removeItem(SOURCE_KEY);
      return null;
    }
    return parsed;
  } catch (e) {
    return null;
  }
}

function readQueryParam(key) {
  try {
    const v = new URLSearchParams(window.location.search).get(key);
    return v && v.length <= 200 ? v : null;
  } catch (e) {
    return null;
  }
}

function isInternalReferrer(referrer) {
  if (!referrer) return false;
  try {
    const host = new URL(referrer).hostname;
    return host === 'www.whaleal.com' || host === 'whaleal.com';
  } catch (e) {
    return false;
  }
}

/**
 * 给 OAuth URL 附加来源参数，让 install 来源能穿过 Shopify 域。
 *
 * 用途：官网发起安装时（/install 输域名 / CTA 按钮）调用，
 * 后端 /api/auth 收到的 query 里就带上了 utm，落库后可与商店关联。
 *
 * @param {string} url 原始 URL
 * @returns {string} 附加来源后的 URL
 */
export function buildTrackingUrl(url) {
  if (!isBrowser() || !url) return url;
  const source = getSourceParams();
  if (!source) return url;
  const { params, referrer } = source;
  const q = new URLSearchParams();
  Object.keys(params).forEach((k) => q.set(k, params[k]));
  // referrer 只带 host+path，去掉查询串，避免把噪声与 PII 带进后端
  if (referrer && !Object.keys(params).length) {
    try {
      const u = new URL(referrer);
      q.set('ref', `${u.hostname}${u.pathname}`);
    } catch (e) {
      // 忽略
    }
  }
  if (![...q.keys()].length) return url;
  q.set('utm_source', q.get('utm_source') || (params.gclid ? 'google_ads' : params.fbclid ? 'meta_ads' : 'referral'));
  return url + (url.includes('?') ? '&' : '?') + q.toString();
}
